import{_ as e,o as a,c as i,a5 as l}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"CSS3 媒体查询","description":"媒体查询（Media Queries）是 CSS3 中的一项强大功能，用于根据不同的设备特性（如屏幕宽度、高度、分辨率等）应用不同的样式。以下是一个全面的媒体查询示例，展示了如何针对不同设备尺寸进行响应式设计。 HTML 文件（index.html） \\\\<!DOCTYPE htm。","frontmatter":{"title":"CSS3 媒体查询","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","前端知识复习"],"description":"媒体查询（Media Queries）是 CSS3 中的一项强大功能，用于根据不同的设备特性（如屏幕宽度、高度、分辨率等）应用不同的样式。以下是一个全面的媒体查询示例，展示了如何针对不同设备尺寸进行响应式设计。 HTML 文件（index.html） \\\\<!DOCTYPE htm。","sidebarWeight":5,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/复习大纲/css/CSS3 媒体查询.md"},"headers":[],"relativePath":"posts/前端面试与实战/01-前端知识复习/css/CSS3 媒体查询.md","filePath":"posts/前端面试与实战/01-前端知识复习/css/CSS3 媒体查询.md"}'),n={name:"posts/前端面试与实战/01-前端知识复习/css/CSS3 媒体查询.md"};function s(o,t,r,d,g,p){return a(),i("div",null,[...t[0]||(t[0]=[l('<div><h1 id="css3-媒体查询" tabindex="-1">CSS3 媒体查询 <a class="header-anchor" href="#css3-媒体查询" aria-label="Permalink to &quot;CSS3 媒体查询&quot;">​</a></h1><blockquote><p>本节目标：理解“CSS3 媒体查询”的核心思路，并能把它用于实际开发或面试表达。 媒体查询（Media Queries）是 CSS3 中的一项强大功能，用于根据不同的设备特性（如屏幕宽度、高度、分辨率等）应用不同的样式。以下是一个全面的媒体查询示例，展示了如何针对不同设备尺寸进行响应式设计。</p></blockquote><p>HTML 文件（index.html） &lt;!DOCTYPE html&gt; &lt;html lang=&quot;en&quot;&gt; &lt;head&gt; &lt;meta charset=&quot;UTF-8&quot;&gt; &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&gt; &lt;title&gt;CSS3 Media Queries Example&lt;/title&gt; &lt;link rel=&quot;stylesheet&quot; href=&quot;styles.css&quot;&gt; &lt;/head&gt; &lt;body&gt; &lt;header&gt; &lt;h1&gt;Responsive Design with Media Queries&lt;/h1&gt; &lt;/header&gt; &lt;nav&gt; &lt;ul&gt; &lt;li&gt;&lt;a href=&quot;#&quot;&gt;Home&lt;/a&gt;&lt;/li&gt; &lt;li&gt;&lt;a href=&quot;#&quot;&gt;About&lt;/a&gt;&lt;/li&gt; &lt;li&gt;&lt;a href=&quot;#&quot;&gt;Services&lt;/a&gt;&lt;/li&gt; &lt;li&gt;&lt;a href=&quot;#&quot;&gt;Contact&lt;/a&gt;&lt;/li&gt; &lt;/ul&gt; &lt;/nav&gt; &lt;main&gt; &lt;section&gt; &lt;h2&gt;Welcome to Our Website&lt;/h2&gt; &lt;p&gt;This is a sample responsive webpage using CSS3 media queries.&lt;/p&gt; &lt;/section&gt; &lt;aside&gt; &lt;h3&gt;Side Content&lt;/h3&gt; &lt;p&gt;This is some additional content that will be positioned differently based on the screen size.&lt;/p&gt; &lt;/aside&gt; &lt;/main&gt; &lt;footer&gt; &lt;p&gt;© 2024 Responsive Design Example&lt;/p&gt; &lt;/footer&gt; &lt;/body&gt; &lt;/html&gt;</p><p><strong>CSS 文件（styles.css）</strong> /* Basic styles for all devices */ body { font-family: Arial, sans-serif; margin: 0; padding: 0; } header, nav, main, aside, footer { padding: 20px; margin: 10px; border: 1px solid #ccc; } header { background-color: #f4f4f4; text-align: center; } nav ul { list-style: none; padding: 0; display: flex; justify-content: center; background-color: #333; } nav ul li { margin: 0 10px; } nav ul li a { color: white; text-decoration: none; padding: 10px 15px; display: block; } nav ul li a:hover { background-color: #575757; } main { display: flex; flex-wrap: wrap; } main section, main aside { flex: 1; min-width: 300px; } footer { text-align: center; background-color: #f4f4f4; }</p><p>/* Media Queries <em>/ /</em> Tablets in landscape and larger */ @media (min-width: 768px) { nav ul { justify-content: space-around; } main { flex-wrap: nowrap; } main section { flex: 2; } main aside { flex: 1; } }</p><p>/* Desktops and larger screens */ @media (min-width: 1024px) { body { margin: 0 auto; max-width: 1200px; } header { text-align: left; } nav ul { justify-content: flex-start; } nav ul li { margin: 0; } main { display: flex; } main section, main aside { margin: 10px; } main section { flex: 3; } main aside { flex: 1; } }</p><p>/* Large screens and up */ @media (min-width: 1440px) { body { max-width: 1400px; } nav ul { justify-content: flex-start; } main { margin: 20px 0; } main section, main aside { padding: 30px; } }</p><h3 id="解释" tabindex="-1">解释 <a class="header-anchor" href="#解释" aria-label="Permalink to &quot;解释&quot;">​</a></h3><ul><li><strong>基本样式</strong>：对所有设备应用的基础样式，包括基本的排版、间距和布局设置。</li><li><strong>媒体查询</strong>：</li><li><strong>平板设备及以上</strong>（最小宽度 768px）：调整导航栏的布局，使导航项之间有更多间距，并将主内容区域和侧边栏布局为横向排列。</li><li><strong>桌面设备及以上</strong>（最小宽度 1024px）：进一步优化布局，使内容在更大屏幕上展示更好，同时限制页面的最大宽度，并调整文本对齐方式和内容间距。</li><li><strong>大屏幕设备及以上</strong>（最小宽度 1440px）：为更大屏幕增加额外的间距和填充，以提升视觉效果和可读性。 通过这些媒体查询，可以确保网页在不同设备和屏幕尺寸上都有良好的用户体验。</li></ul></div>',1)])])}const u=e(n,[["render",s]]);export{m as __pageData,u as default};
